"""The source-to-tools-to-memory continuation, using the same synthetic note."""
from html import escape

def continuation(lang,data):
    def t(a,b):return a if lang=='zh' else b
    n=data['note'];quote=escape(n['quote_'+lang]);title=escape(n['title_'+lang]);source='note / NOTE_ID / v1'
    badge=f'<span class="memory-badge" data-memory-badge data-candidate="{t("关联记忆：待确认","Linked memory: pending")}" data-confirmed="{t("关联记忆：已确认","Linked memory: confirmed")}" data-inactive="{t("关联记忆：已停用","Linked memory: inactive")}">{t("关联记忆：待确认","Linked memory: pending")}</span>'
    rows=[('note','10:35',title,quote),('recording','09:10',t('散步时的一个念头','A thought from a walk'),t('原音 00:42 · 待添加文字 · DEMO_AUDIO','Original audio 00:42 · Text not added · DEMO_AUDIO')),('input','16:20','Codex / Claude Code',t('一次工具会话，保留原来的上下文。','A tool session, with its original context.')),('document','—',t('产品演示提纲.md','Product demo outline.md'),t('已有文字资料，保留可用时间与来源。','Existing text, with its available time and source.'))]
    rowhtml=''.join(f'<article data-library-kind="{kind}"><span class="index-kind">{kind}</span><div><h3>{name}</h3><p>{body}</p></div><time>{time}</time><span class="mono">v1</span></article>' for kind,time,name,body in rows)
    rowhtml=rowhtml.replace('<h3>'+title+'</h3>', '<h3><a href="#work-source" data-source-route>'+title+'</a></h3>')
    commands=['python3 integrations/lifto-library/scripts/lifto.py search "'+t('产品演示','product demo')+'" --scope notes','python3 integrations/lifto-library/scripts/lifto.py query "'+t('产品演示','product demo')+'" --scope notes','python3 integrations/lifto-library/scripts/lifto.py read note NOTE_ID']
    command_buttons=''.join(f'<button type="button" data-command-step="{i}" aria-pressed="{"true" if i==0 else "false"}" data-command="{escape(cmd,quote=True)}" hidden><span>0{i+1}</span>{label}</button>' for i,(cmd,label) in enumerate(zip(commands,[t('查找','Search'),t('查询','Query'),t('读取','Read')])))
    return f'''<section class="library-section section-pad" id="library"><div class="section-heading"><p class="overline">03 / {t('资料汇集','YOUR LIBRARY')}</p><h2>{t('散在各处。<br>仍有来处。','Different places.<br>Every source intact.')}</h2><p>{t('笔记、已有文字、导出的聊天与已适配的工具会话。先预览，再确认导入。','Notes, existing text, exported chats and adapted tool sessions. Preview first, then confirm the import.')}</p></div><div class="library-index"><div class="index-toolbar"><span>{t('秋季产品演示 / 合成资料','AUTUMN PRODUCT DEMO / SYNTHETIC MATERIAL')}</span><div class="filter-controls" data-library-filters hidden>'''+''.join(f'<button type="button" data-kind="{kind}" aria-pressed="{"true" if kind=="all" else "false"}">{label}</button>' for kind,label in [('all',t('全部','All')),('recording',t('录音','Audio')),('note',t('笔记','Notes')),('input',t('工具会话','Sessions')),('document',t('文档','Documents'))])+f'''</div></div><div class="index-columns" aria-hidden="true"><span>{t('类型','TYPE')}</span><span>{t('资料与来源','MATERIAL & SOURCE')}</span><span>{t('可用时间','TIME')}</span><span>{t('版本','VER.')}</span></div>{rowhtml}<p class="index-status" role="status" data-library-status data-label="{t('条来源','sources')}" data-singular="{t('条来源','source')}">4 {t('条来源','sources')}</p></div><details class="quiet-details"><summary>{t('格式与来源时间','Formats and source time')}</summary><p>{t('支持已适配的 UTF-8 文字格式（.md / .markdown / .txt / .text）和 PDF 已有文字，不做扫描件 OCR，不代表支持 Office。聊天导入归笔记，Codex 与 Claude Code 会话归工具输入。文件可能只有修改或导入时间，未知时间会明确标记。导入不等于发送给模型。','Adapted UTF-8 text formats (.md / .markdown / .txt / .text) and existing PDF text, not scanned-page OCR or general Office support. Imported chats become notes; Codex and Claude Code sessions become tool inputs. A file may only have a modification or import time; unknown times are marked. Importing does not send material to a model.')}</p></details></section>
<section class="workbench" id="workbench"><div class="workbench-motion"><div class="workbench-stage"><div class="section-heading"><p class="overline">04 / {t('带着来源，继续工作','CONTINUE WITH THE SOURCE')}</p><h2>{t('换一个工具。<br>不用换一段记忆。','A different tool.<br>The same thread.')}</h2><p>{t('让已授权的工具找到原文，而不是重新猜你的背景。','Let an authorized tool find the original, rather than guess your context again.')}</p></div><div class="workbench-grid"><div class="terminal-side"><div class="command-tabs">{command_buttons}</div><p class="terminal-label">{t('命令示例 · 不执行命令','COMMAND EXAMPLE · NOT EXECUTED')}</p><pre class="terminal-command"><span>$ </span><code data-command-output>{escape(commands[0])}</code></pre><div class="terminal-results"><div data-command-result="0"><span>01 · note / NOTE_ID / v1</span><h3>{title}</h3><p>10/21 · 10:35</p><span>02 · note / NOTE_02 / v1</span><p>{t('周四彩排','Thursday rehearsal')}</p></div><div data-command-result="1" hidden><span>{t('检索摘句，不是模型回答','RETRIEVED PASSAGE, NOT A MODEL ANSWER')}</span><blockquote>{quote}</blockquote><p>note / NOTE_ID / v1</p></div><div data-command-result="2" hidden><span>note / NOTE_ID / v1</span><p>{t('原文已展开在旁边。','The original is open beside this command.')}</p></div></div><button class="source-citation" type="button" data-work-citation hidden>[1] {t('对照原文','Check the source')}<span class="arrow" aria-hidden="true"></span></button><a class="work-fallback" href="#work-source">{t('阅读原文','Read the original')}</a></div><article class="work-source" id="work-source" tabindex="-1"><div class="source-reader-top"><span>{t('原文','ORIGINAL SOURCE')}</span><span class="mono">{source}</span></div><h3>{title}</h3><div data-source-excerpt><blockquote data-original-quote><mark>{quote}</mark></blockquote></div><div data-source-full><p class="source-date">10/21 · 10:35</p><p>{t('让观众先看见依据，再解释整理过程。','Let the audience see the evidence before explaining the organization.')}</p>{badge}<a class="memory-route" href="#memory">{t('看看基于它的记忆','See the memory based on it')}<span class="arrow" aria-hidden="true"></span></a></div></article></div></div></div><details class="quiet-details workbench-conditions"><summary>{t('只读授权与运行条件','Read-only access and setup')}</summary><p>{t('从仓库根目录执行，先配置 LIFTO_URL 与独立只读凭证文件路径 LIFTO_TOKEN_FILE。NOTE_ID 需替换为检索返回的真实编号。仅 capabilities / search / query / read，不写文件、不批准记忆、不录音、不改设置。工具会话归档和只读检索是两个方向。','Run from the repository root after configuring LIFTO_URL and LIFTO_TOKEN_FILE, the path to a separate scoped credential file. Replace NOTE_ID with the real identifier returned by retrieval. Only capabilities / search / query / read: no file writes, memory approvals, recording or settings changes. Session archiving and read-only retrieval are separate directions.')}</p></details></section>
<section class="memory-section section-pad" id="memory"><div class="section-heading"><p class="overline">05 / {t('由你决定','YOUR DECISION')}</p><h2>{t('留下哪一部分。<br>决定权在你。','What stays.<br>You decide.')}</h2><p>{t('候选不等于事实。对照原文，再由你确认。','A candidate is not a fact. Check the source, then decide.')}</p></div><div class="memory-workspace"><aside class="memory-evidence"><p class="overline">{t('依据没有离开','THE SOURCE STAYS CLOSE')}</p><span class="mono">{source}</span><blockquote>{quote}</blockquote><a href="#work-source" data-source-route>{t('回到这条原文','Return to this source')}<span class="arrow" aria-hidden="true"></span></a></aside><div class="memory-decision" data-memory-state="candidate"><div class="memory-state-line"><span class="state-point" aria-hidden="true"></span><p role="status" id="memory-state" tabindex="-1" data-memory-status data-candidate="{t('手动候选 · 等待本人确认','Manual candidate · Awaiting your confirmation')}" data-confirmed="{t('已确认 · v1 · 原文依据保留','Confirmed · v1 · Source retained')}" data-inactive="{t('已停用 · 历史与依据保留','Inactive · History and source retained')}">{t('手动候选 · 等待本人确认','Manual candidate · Awaiting your confirmation')}</p></div><h3>{t('秋季产品演示：<br>先展示原文，再展示整理结果。','Autumn product demo:<br>show the original before the organized result.')}</h3><p class="memory-basis">{t('基于 NOTE_ID 的这次安排，不是永久个人偏好。','An arrangement based on NOTE_ID, not a permanent personal preference.')}</p><div class="memory-actions"><button type="button" data-memory-action data-state="candidate" data-confirm="{t('确认这条记忆','Confirm this memory')}" data-deactivate="{t('停用这条记忆','Deactivate this memory')}" data-restore="{t('恢复这条记忆','Restore this memory')}" hidden>{t('确认这条记忆','Confirm this memory')}</button><button type="button" class="text-button" data-memory-reset hidden>{t('重置网页演示','Reset web demo')}</button></div><span class="memory-note">{t('本页只操作合成示例，不写入客户端。','This page changes only the synthetic example, not your client.')}</span></div></div><details class="quiet-details"><summary>{t('修订、停用与恢复','Revision, deactivation and recovery')}</summary><p>{t('四类来源支持手动候选、确认、修订、停用与恢复，保留原文片段、内容版本和历史。确认后可停用再恢复，不是退回待确认。可明确发起模型候选与批量整理，仍由人确认；定时批量整理与自动关系判断尚未实现。','Four source kinds support manual candidates, confirmation, revision, deactivation and recovery, with source excerpts, content versions and history. A confirmed memory may be deactivated and restored, not returned to pending. Model candidates and batch organization can be explicitly requested and still require human confirmation; scheduled batch organization and automatic relationship judgments are not implemented.')}</p></details></section>
<section class="files-section section-pad"><div class="section-heading"><p class="overline">06 / {t('资料归你','YOURS TO KEEP')}</p><h2>{t('不只留在一个回答里。','Beyond a single answer.')}</h2><p>{t('原始文字、来源与版本。放在你选择的资料夹，也能带走。','Original text, sources and versions. In a folder you choose, and yours to take.')}</p></div><div class="file-workspace"><div class="file-tree"><span class="folder-mark" aria-hidden="true"></span><h3>{t('我的资料','My material')}</h3><ul><li>{t('原始文字','Original text')}<span>.md</span></li><li>{t('记忆文字与依据','Memory and evidence')}<span>.md</span></li><li>{t('内容历史','Content history')}<span>v1…</span></li></ul><p>{t('文件组织示意，不是客户端截图。','File organization illustration, not a client screenshot.')}</p></div><div class="file-preview"><div class="file-caption"><span>NOTE_ID.md</span><span>{t('文字导出示意','TEXT EXPORT EXAMPLE')}</span></div><pre><code># {title}

source: note / NOTE_ID
content_version: 1

{quote}</code></pre></div></div><p class="export-boundary">{t('便携文字导出不含原音或凭证。不是完整备份，也不是自动恢复包；产品另有独立备份与恢复。','Portable text export excludes original audio and credentials. It is not a complete backup or automatic restore package; separate backup and restoration are available in the product.')}</p></section>'''
